// Validation et préparation des données
const input = $input.first().json;
const body = input.body || input;

const startTime = Date.now();

// Extraction des paramètres
const text = body.text || '';
const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';
const targetLanguage = body.target_language || 'fr';
const sourceLanguage = body.source_language || 'auto';
const sourceTextId = body.source_text_id || null;
const commentaryId = body.commentary_id || null;
const context = body.context || {};
const discord = body.discord || {};
const requestId = body.request_id || null;

// Mode: standard ou premium
const mode = body.mode || 'standard';
const validModes = ['standard', 'premium'];
const selectedMode = validModes.includes(mode) ? mode : 'standard';

// Pivot: utiliser la traduction via l'anglais
const usePivot = body.use_pivot === true;

// Configuration des modèles selon le mode
const modelConfig = {
  standard: {
    claude: 'claude-sonnet-4-20250514',
    openai: 'gpt-4o'
  },
  premium: {
    claude: 'claude-haiku-4.5',
    openai: 'gpt-5-mini'
  }
};

const models = modelConfig[selectedMode];

// Validation
const errors = [];
if (!text || text.trim().length === 0) {
  errors.push('Le champ "text" est requis');
}
if (!apiKey || apiKey.trim().length === 0) {
  errors.push('Le champ "api_key" (Anthropic) est requis');
}
if (!openaiApiKey || openaiApiKey.trim().length === 0) {
  errors.push('Le champ "openai_api_key" est requis');
}

// Mapping langues
const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen'
};

const targetLangName = languageNames[targetLanguage] || 'français';
const sourceLangName = sourceLanguage === 'auto' ? null : (languageNames[sourceLanguage] || sourceLanguage);

// Construction du contexte pour le prompt
let contextInfo = '';
if (context.traite || context.page || context.commentator) {
  contextInfo = `\n\nContexte: ${context.commentator || ''} sur ${context.traite || ''} ${context.page || ''}`.trim();
}

// Construire l'URL de recherche cache
let cacheSearchParams = `target_language=${targetLanguage}`;
if (sourceTextId) {
  cacheSearchParams += `&source_text_id=${sourceTextId}`;
} else if (commentaryId) {
  cacheSearchParams += `&commentary_id=${commentaryId}`;
} else if (context.traite && context.page) {
  cacheSearchParams += `&traite=${encodeURIComponent(context.traite)}&page=${encodeURIComponent(context.page)}`;
  if (context.commentator) {
    cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
  }
  cacheSearchParams += `&text=${encodeURIComponent(text)}&exact=true`;
}

// Construire le payload pour le pivot workflow
const pivotPayload = {
  text: text,
  api_key: apiKey,
  openai_api_key: openaiApiKey,
  source_language: sourceLanguage === 'auto' ? 'he' : sourceLanguage,
  target_language: targetLanguage,
  mode: selectedMode,
  context: context,
  discord: discord,
  request_id: requestId
};

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    text: text,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey,
    targetLanguage: targetLanguage,
    targetLangName: targetLangName,
    sourceLanguage: sourceLanguage,
    sourceLangName: sourceLangName,
    sourceTextId: sourceTextId,
    commentaryId: commentaryId,
    contextInfo: contextInfo,
    context: context,
    discord: discord,
    requestId: requestId,
    startTime: startTime,
    cacheSearchParams: cacheSearchParams,
    canSearchCache: !!(sourceTextId || commentaryId || (context.traite && context.page)),
    isCommentary: !!commentaryId,
    mode: selectedMode,
    claudeModel: models.claude,
    openaiModel: models.openai,
    usePivot: usePivot,
    pivotPayload: pivotPayload
  }
}];

// Vérifier si le cache a retourné une traduction
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Cache hit si status 200 et traduction trouvée
const cacheHit = statusCode === 200 && data.found === true && data.translations && data.translations.length > 0;

if (cacheHit) {
  const cached = data.translations[0];
  return [{
    json: {
      cacheHit: true,
      translation: cached.translated_text,
      qualityScore: cached.quality_score || 0.9,
      provider: cached.provider || 'cached',
      model: cached.model || 'cached',
      cachedAt: cached.created_at,
      // Passer les données pour la réponse
      originalText: prevData.text,
      targetLanguage: prevData.targetLanguage,
      context: prevData.context,
      discord: prevData.discord,
      requestId: prevData.requestId,
      startTime: prevData.startTime
    }
  }];
}

// Cache miss - passer au traducteur
return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Formater la réponse depuis le cache
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

// llm_usage base pour cache hit (0 tokens)
const llmUsage = [{
  model: 'database',
  provider: 'base',
  input_tokens: 0,
  output_tokens: 0,
  total_tokens: 0
}];

return [{
  json: {
    success: true,
    cached: true,
    requestId: input.requestId,
    translation: {
      original: input.originalText,
      translated: input.translation,
      source_language: 'he',
      target_language: input.targetLanguage,
      quality_score: input.qualityScore
    },
    verification: {
      approved: true,
      confidence: input.qualityScore,
      issues: [],
      notes: 'Traduction depuis le cache'
    },
    alternatives: null,
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      models_used: [input.provider || 'cached'],
      source: 'cache',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    },
    llm_usage: llmUsage,
    total_tokens: 0,
    discord: input.discord
  }
}];

