// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Formater la réponse du workflow pivot
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Si erreur HTTP
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || 'Erreur appel workflow pivot',
        status: 'PIVOT_WORKFLOW_ERROR'
      }
    }
  }];
}

// Passer la réponse du pivot avec le discord pour notification
const response = { ...data };
response.discord = prevData.discord;
response.pivot_used = true;

return [{ json: response }];

// Vérifier si le commentaire a une traduction
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode;

// Si erreur de connexion (error.code est une string comme 'ERR_BAD_REQUEST')
if (input.error && typeof input.error.code === 'string') {
  return [{
    json: {
      hasTranslation: false,
      ...prevData
    }
  }];
}

// Si erreur HTTP, passer à la traduction
if (typeof statusCode === 'number' && statusCode >= 400) {
  return [{
    json: {
      hasTranslation: false,
      ...prevData
    }
  }];
}

// Vérifier si la traduction existe
const translations = data.translations || {};
const translation = translations[prevData.commentaryId];

if (translation && translation.text) {
  return [{
    json: {
      hasTranslation: true,
      cachedTranslation: translation.text,
      cachedProvider: translation.provider || 'cached',
      cachedModel: translation.model || 'cached',
      cachedAt: translation.translated_at,
      originalText: prevData.text,
      targetLanguage: prevData.targetLanguage,
      context: prevData.context,
      discord: prevData.discord,
      requestId: prevData.requestId,
      startTime: prevData.startTime,
      commentaryId: prevData.commentaryId
    }
  }];
}

// Pas de traduction, passer à Claude
return [{
  json: {
    hasTranslation: false,
    ...prevData
  }
}];

// Formater la réponse pour le commentaire depuis la BDD
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    status: 'cached',
    requestId: input.requestId,
    translation: {
      original: input.originalText,
      translated: input.cachedTranslation,
      source_language: 'he',
      target_language: input.targetLanguage,
      quality_score: 0.95
    },
    verification: {
      approved: true,
      confidence: 0.95,
      issues: [],
      notes: 'Traduction existante depuis la base de données'
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      commentary_id: input.commentaryId,
      models_used: [input.cachedProvider || 'database'],
      source: 'database',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    },
    llm_usage: [{
      model: 'database',
      provider: 'cache',
      input_tokens: 0,
      output_tokens: 0,
      total_tokens: 0
    }],
    total_tokens: 0,
    discord: input.discord
  }
}];
